import { beforeEach, describe, expect, it, vi } from "vitest";
const mocks = vi.hoisted(() => ({
  subscriptions: vi.fn(),
  attempts: vi.fn(),
  users: vi.fn(),
  inbox: vi.fn(),
  count: vi.fn(),
  current: vi.fn(),
  touch: vi.fn(),
  cleanup: vi.fn(),
  process: vi.fn(),
  reconcile: vi.fn(),
  cancel: vi.fn(),
  checkout: vi.fn(),
  deletion: vi.fn(),
  config: vi.fn(),
}));
vi.mock("@/lib/billing/config", () => ({ billingConfig: mocks.config }));
vi.mock("@/lib/billing/lifecycle", () => ({
  processBillingEvent: mocks.process,
  reconcileBillingSubscription: mocks.reconcile,
}));
vi.mock("@/lib/billing/cancel", () => ({
  recoverBillingCancellation: mocks.cancel,
}));
vi.mock("@/lib/billing/checkout", () => ({
  recoverCheckoutAttempt: mocks.checkout,
}));
vi.mock("@/lib/billing/deletion", () => ({
  stopBillingForDeletion: mocks.deletion,
}));
vi.mock("@/lib/db", () => ({
  db: {
    billingSubscription: {
      findMany: mocks.subscriptions,
      findFirst: mocks.current,
      updateMany: mocks.touch,
    },
    checkoutAttempt: { findMany: mocks.attempts, updateMany: mocks.touch },
    user: { findMany: mocks.users },
    billingWebhookEvent: { findMany: mocks.inbox, count: mocks.count },
    billingRateLimit: { deleteMany: mocks.cleanup },
  },
}));
import {
  reconcileBilling,
  reconcileBillingPage,
  recoverBilling,
  retryBillingInbox,
} from "@/lib/billing/jobs";
beforeEach(() => {
  vi.clearAllMocks();
  mocks.subscriptions.mockResolvedValue([]);
  mocks.attempts.mockResolvedValue([]);
  mocks.users.mockResolvedValue([]);
  mocks.inbox.mockResolvedValue([]);
  mocks.current.mockResolvedValue({
    status: "ACTIVE",
    settledPaymentId: "pay_fixture",
    periodEnd: new Date(Date.now() + 86400_000),
  });
  mocks.count.mockResolvedValue(0);
});
describe("durable billing jobs", () => {
  it("paginates with a stable cutoff, continues failures, and reports missing settlement", async () => {
    const rows = Array.from({ length: 50 }, (_, i) => ({
      id: String(i).padStart(3, "0"),
      userId: "owner",
      dodoSubscriptionId: `sub_${i}`,
    }));
    mocks.subscriptions.mockResolvedValueOnce(rows).mockResolvedValueOnce([]);
    mocks.reconcile.mockRejectedValueOnce(new Error("provider offline"));
    mocks.current.mockResolvedValue({
      status: "ACTIVE",
      settledPaymentId: null,
    });
    const cutoff = new Date().toISOString();
    const first = await reconcileBillingPage(null, cutoff);
    expect(first).toEqual({
      cursor: "049",
      scanned: 50,
      failed: 1,
      missingSettlement: 49,
    });
    expect(await reconcileBillingPage(first.cursor, cutoff)).toEqual({
      cursor: null,
      scanned: 0,
      failed: 0,
      missingSettlement: 0,
    });
    expect(mocks.subscriptions).toHaveBeenLastCalledWith(
      expect.objectContaining({
        take: 50,
        where: expect.objectContaining({
          id: { gt: "049" },
          createdAt: { lte: new Date(cutoff) },
        }),
      }),
    );
  });
  it("keeps processing the inbox after one receipt fails", async () => {
    mocks.inbox.mockResolvedValue([{ id: "failed" }, { id: "succeeded" }]);
    mocks.process.mockRejectedValueOnce(new Error("provider unavailable"));
    expect(await retryBillingInbox()).toEqual({ processed: 1, pending: 1 });
    expect(mocks.process).toHaveBeenCalledTimes(2);
  });
  it("continues checkout and subscription recovery after individual failures", async () => {
    mocks.users.mockResolvedValue([{ id: "deleted" }]);
    mocks.deletion.mockRejectedValueOnce(new Error("unavailable"));
    mocks.attempts.mockResolvedValue([{ userId: "owner", id: "attempt" }]);
    mocks.checkout.mockRejectedValueOnce(new Error("uncertain"));
    mocks.subscriptions.mockResolvedValue([
      { userId: "owner", dodoSubscriptionId: "sub_1" },
      { userId: "owner", dodoSubscriptionId: "sub_2" },
    ]);
    mocks.reconcile.mockRejectedValueOnce(new Error("unavailable"));
    expect(await recoverBilling()).toMatchObject({
      failed: 1,
      subscriptions: 2,
    });
    expect(mocks.touch).toHaveBeenCalledTimes(2);
    expect(mocks.reconcile).toHaveBeenCalledTimes(2);
  });
  it("reports an incomplete nightly run without a job service", async () => {
    mocks.subscriptions.mockResolvedValueOnce([
      { id: "row", userId: "owner", dodoSubscriptionId: "sub" },
    ]);
    mocks.reconcile.mockRejectedValueOnce(new Error("provider offline"));
    const diagnostic = vi.spyOn(console, "info").mockImplementation(() => {});
    try {
      await expect(reconcileBilling()).rejects.toThrow(
        "BILLING_NIGHTLY_INCOMPLETE",
      );
      expect(diagnostic).toHaveBeenCalledWith(
        expect.stringContaining('"event":"nightly"'),
      );
    } finally {
      diagnostic.mockRestore();
    }
  });
  it("completes nightly reconciliation without an event publisher", async () => {
    expect(await reconcileBilling()).toEqual({
      scanned: 0,
      failed: 0,
      missingSettlement: 0,
    });
  });
});
